-- A store as this code wrote it at layout version 2, once each run saved
-- its choice of model as route_decided, run_started saved whether the run
-- is private, and model_request saved the name of the model asked. It
-- holds the same chats as version_2_tools.sql. Never edit this file: a
-- change that breaks old data must fail the test that reads it.
PRAGMA application_id = 1279348048;
PRAGMA user_version = 2;
BEGIN TRANSACTION;
CREATE TABLE effects (
  effect_id    INTEGER PRIMARY KEY AUTOINCREMENT,
  effect_key   TEXT    NOT NULL UNIQUE,
  v            INTEGER NOT NULL CHECK (v >= 1),
  session_id   TEXT    NOT NULL,
  state        TEXT    NOT NULL,
  action       TEXT    NOT NULL,
  probe        TEXT,
  undo         TEXT,
  result       TEXT,
  resolution   TEXT,
  begun_at     TEXT    NOT NULL,
  finished_at  TEXT,
  resolved_at  TEXT
) STRICT;
CREATE TABLE events (
  pos          INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id   TEXT    NOT NULL,
  seq          INTEGER NOT NULL CHECK (seq >= 1),
  type         TEXT    NOT NULL,
  v            INTEGER NOT NULL CHECK (v >= 1),
  event_id     TEXT    NOT NULL,
  run_id       TEXT,
  step         INTEGER,
  at           TEXT    NOT NULL,
  duration_ms  INTEGER,
  cause        TEXT,
  payload      TEXT    NOT NULL,
  UNIQUE (session_id, seq),
  UNIQUE (event_id)
) STRICT;
CREATE TABLE inbox (
  inbox_id           INTEGER PRIMARY KEY AUTOINCREMENT,
  channel            TEXT    NOT NULL,
  native_id          TEXT    NOT NULL,
  inbound            TEXT    NOT NULL,
  routed_session_id  TEXT,
  routed_seq         INTEGER,
  UNIQUE (channel, native_id)
) STRICT;
CREATE TABLE outbox (
  outbox_id        INTEGER PRIMARY KEY AUTOINCREMENT,
  out_id           TEXT    NOT NULL UNIQUE,
  session_id       TEXT    NOT NULL,
  v                INTEGER NOT NULL CHECK (v >= 1),
  state            TEXT    NOT NULL,
  outbound         TEXT    NOT NULL,
  maybe_duplicate  INTEGER NOT NULL DEFAULT 0,
  receipt          TEXT,
  last_failure     TEXT,
  enqueued_at      TEXT    NOT NULL,
  sent_at          TEXT
) STRICT;
CREATE INDEX events_run_marks ON events (session_id, seq, type)
  WHERE type IN ('run_started', 'run_end');
CREATE INDEX effects_unresolved ON effects (effect_id)
  WHERE state IN ('intended', 'unknown');
CREATE INDEX inbox_pending ON inbox (inbox_id)
  WHERE routed_session_id IS NULL;
CREATE INDEX outbox_due ON outbox (outbox_id)
  WHERE state IN ('pending', 'sending');
DELETE FROM "sqlite_sequence";
COMMIT;
